// Republic of Ostara passport spread — make.fun entry.
// Writes the pre-rendered, deterministic entry.png to the output directory.
// The image itself is generated by generate.py (PIL, no network, no
// randomness, verified byte-identical across runs); this entrypoint only
// places the exact committed bytes at /output/entry.png, then verifies the
// copy byte-for-byte so a partial write can never pass silently.
import { copyFileSync, mkdirSync, readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = process.env.OUTPUT_DIR || "/output";
const src = join(here, "entry.png");
const dst = join(outDir, "entry.png");

// Read and sanity-check the source: must be a 1024x1024 PNG under 1 MiB.
const bytes = readFileSync(src);
if (bytes.length > 1_048_576) throw new Error(`entry.png too large: ${bytes.length} bytes`);
if (!bytes.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) {
  throw new Error("entry.png is not a PNG");
}
const width = bytes.readUInt32BE(16);
const height = bytes.readUInt32BE(20);
if (width !== 1024 || height !== 1024) {
  throw new Error(`entry.png must be 1024x1024, got ${width}x${height}`);
}

mkdirSync(outDir, { recursive: true });
copyFileSync(src, dst);

// Verify the copy is byte-identical to the source.
const digest = (b: Buffer) => createHash("sha256").update(b).digest("hex");
if (digest(readFileSync(dst)) !== digest(bytes)) {
  throw new Error("entry.png copy failed verification");
}
console.log(`wrote entry.png (${bytes.length} bytes, sha256 ${digest(bytes)})`);
